<?php require_once __DIR__.'/bootstrap.php'; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['product_id']??0);if($action==='add'&&$id>0){$s=$pdo->prepare('SELECT id FROM products WHERE id=? AND active=1');$s->execute([$id]);if($s->fetch())$_SESSION['cart'][$id]=min(20,(int)($_SESSION['cart'][$id]??0)+1);}if($action==='remove'&&$id>0)unset($_SESSION['cart'][$id]);if($action==='qty'&&$id>0){$qty=max(0,min(20,(int)($_POST['quantity']??0)));if($qty===0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=$qty;}header('Location: cart.php');exit;}$cart=$_SESSION['cart']??[];$items=[];$total=0;if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE active=1 AND id IN ($in)");$s->execute($ids);foreach($s as $p){$p['quantity']=(int)$cart[$p['id']];$p['line_total']=$p['price']*$p['quantity'];$total+=$p['line_total'];$items[]=$p;}}page_start('Your cart'); ?><h1>Your cart</h1><?php if(!$items):?><div class="panel">Your cart is empty. <a href="index.php">Browse products</a></div><?php else:?><div class="panel"><table><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><?=e($p['title'])?></td><td><?=money($p['price'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="qty"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><input type="number" name="quantity" value="<?=(int)$p['quantity']?>" min="0" max="20" style="width:90px;margin:0"><button class="secondary">Update</button></form></td><td><?=money($p['line_total'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><button style="background:#a52828">Remove</button></form></td></tr><?php endforeach ?></tbody></table><h2>Total: <?=money($total)?></h2><a class="btn" href="checkout.php">Continue to checkout</a></div><?php endif;page_end();?>
